 "@timestamp": "2026-03-04T19:40:34.736Z",
 "log": {
 "level": "INFO",
 "logger": "elasticsearch.querylog"
 },
 "event": {
 "duration": 1000000,
 "outcome": "success"
 },
 "elasticsearch": {
 "querylog": {
 "type": "dsl",
 "query": "{\"size\":10,\"query\":{\"match_all\":{\"boost\":1.0}}}",
 "indices": ["query_log_test_index"],
 "result_count": 3,
 "search": { "total_count": 3 },
 "shards": { "successful": 1 },
 "took": 1000000,
 "took_millis": 1
 },
 "node": { "name": "node-1" },
 "cluster": { "name": "my-es-cluster" }
 },
 "http": {
 "request": {
 "headers": { "x_opaque_id": "opaque-1772653234" }
 }
 },
 "user": {
 "name": "elastic",
 "realm": "reserved"
 }
}
```

Failure (EQL query):

```
{
 "@timestamp": "2026-03-04T19:40:35.271Z",
 "log": {
 "level": "INFO",
 "logger": "elasticsearch.querylog"
 },
 "event": {
 "duration": 1326334,
 "outcome": "failure"
 },
 "elasticsearch": {
 "querylog": {
 "type": "eql",
 "query": "any where true",
 "indices": ["nonexistent_index_xyz"],
 "result_count": 0,
 "took_millis": 1
 },
